extract_abbr_from_text.source:
def extract_abbr_from_text(text: str) -> str:
    if not text:
        return "<UNK>"
    # 先抓键值对形式：Abbreviation: ...
    m = re.search(r'(?:^|\n)\s*Abbreviation\s*:\s*([^\n\r]+)', text, flags=re.I)
    if m:
        cand = m.group(1).strip()
        cz = _canon(cand)
        for a in ABBR_SET:
            if _canon(a) == cz:
                return a
        # 再宽松找一次
        for abbr in ABBR_SET:
            pat = r'\b' + re.sub(r'\s+', r'\\s*', re.escape(abbr)) + r'\b'
            if re.search(pat, cand, flags=re.IGNORECASE):
                return abbr

    # 规范化直接命中（对全文）
    cz = _canon(text)
    for a in ABBR_SET:
        if _canon(a) == cz:
            return a

    # 正则宽松匹配（允许空白差异）
    for abbr in ABBR_SET:
        pat = r'\b' + re.sub(r'\s+', r'\\s*', re.escape(abbr)) + r'\b'
        if re.search(pat, text, flags=re.IGNORECASE):
            return abbr
    # 全称也兜底匹配
    for full, abbr in FULL2ABBR.items():
        pat = r'\b' + re.sub(r'\s+', r'\\s*', re.escape(full)) + r'\b'
        if re.search(pat, text, flags=re.IGNORECASE):
            return abbr
    return "<UNK>"

