def extract_reason_from_text(text: str) -> str:
    """优先抓 'Reason:' 行；否则取第二个非空行；再不行给空串。"""
    if not text:
        return ""
    m = re.search(r'(?:^|\n)\s*Reason\s*:\s*(.+)', text, flags=re.I | re.DOTALL)
    if m:
        reason = m.group(1).strip().splitlines()[0].strip()
        return reason
    # 无 Reason:，取第二行（非空）
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    if len(lines) >= 2:
        # 如果第二行仍有“Reason:”前缀，清理掉
        return re.sub(r'^\s*Reason\s*:\s*', '', lines[1], flags=re.I).strip()
    return ""

extract_abbr.source:
def extract_abbr(text: str) -> str:
    if not text:
        return "<UNK>"
    # 1) 直接匹配缩写（优先精确）
    m = ABBR_REGEX.search(text)
    if m:
        hit = m.group(1)
        # 归一化回标准大小写/空格
        for a in ABBR_SET:
            if _canon(a) == _canon(hit):
                return a
    # 2) 纯字母规范后命中
    cz = _canon(text)
    if cz in ABBR_CANON_MAP:
        return ABBR_CANON_MAP[cz]
    # 3) 如果写了全称，也容错一下
    for full, ab in FULL2ABBR.items():
        if re.search(r'\b' + re.escape(full) + r'\b', text, flags=re.I):
            return ab
    return "<UNK>"

extract_reason.source:
def extract_reason(text: str) -> str:
    """
    规则：
    - 取 'assistantfinal' 之后的内容中，优先找以 'Reason:' 开头的行
    - 否则尝试第一行之外的剩余文本
    - 长度做一次适度截断（安全）
    """
    if not text:
        return ""
    body = text.split('assistantfinal')[-1]
    lines = [ln.strip() for ln in body.splitlines() if ln.strip()]
    if not lines:
        return ""
    # 搜索 Reason: 行
    for ln in lines:
        if re.match(r'^\s*reason\s*[:\-]\s*(.+)$', ln, flags=re.I):
            return re.sub(r'^\s*reason\s*[:\-]\s*', '', ln, flags=re.I).strip()
    # 否则：把第一行视作缩写行，其余拼接为 reason
    if len(lines) >= 2:
        return " ".join(lines[1:]).strip()
    return ""

extract_abbr_from_text.source:
def extract_abbr_from_text(text: str) -> str:
    if not text:
        return "<UNK>"
    cz = _canon(text)
    if cz in {_canon(a): a for a in ABBR_SET}:
        for a in ABBR_SET:
            if _canon(a) == cz:
                return a
    for abbr in ABBR_SET:
        pat = r'\b' + re.sub(r'\s+', r'\\s*', re.escape(abbr)) + r'\b'
        if re.search(pat, text, flags=re.IGNORECASE):
            return abbr
    for full, abbr in FULL2ABBR.items():
        pat = r'\b' + re.sub(r'\s+', r'\\s*', re.escape(full)) + r'\b'
        if re.search(pat, text, flags=re.IGNORECASE):
            return abbr
    return "<UNK>"

